def skill():
    t, C = symbols('t C')
    v1 = 3*t**2 - 12*t + 9
    v2 = integrate(3*t**2, t) + C
    C0 = solve(v2.subs(t, 3) - v1.subs(t, 3), C)[0]
    v2 = v2.subs(C, C0)
    def dist(v, a, b):
        F = integrate(v, t)
        pts = [a] + sorted(r for r in solve(v, t) if r.is_real and a < r < b) + [b]
        return sum(abs(F.subs(t, q) - F.subs(t, p)) for p, q in zip(pts[:-1], pts[1:]))
    return dist(v1, 0, 3) + dist(v2, 3, 5)

def standard():
    t = Symbol('t')
    v1 = 3*t**2 - 12*t + 9
    v2 = t**3 - 27
    assert v1.subs(t, 3) == v2.subs(t, 3)
    assert diff(v2, t) == 3*t**2
    def dist(v, lo, hi):
        F = integrate(v, t)
        cuts = sorted(r for r in real_roots(Poly(v, t)) if lo < r < hi)
        pts = [lo] + cuts + [hi]
        return sum(abs(F.subs(t, q) - F.subs(t, p)) for p, q in zip(pts[:-1], pts[1:]))
    return dist(v1, 0, 3) + dist(v2, 3, 5)

def unique():
    return [standard()]
